@@ -0,0 +1,17 @@
+export default {
+	html: `
+		<button>update</button>
+		<p>foo: 0</p>
+		<p>bar: 0</p>
+	`,
+
+	async test({ assert, target, window }) {
+		await target.querySelector('button').dispatchEvent(new window.MouseEvent('click'));
+
+		assert.htmlEqual(target.innerHTML, `
+			<button>update</button>
+			<p>foo: 1</p>
+			<p>bar: 2</p>
+		`);
+	}
+};
diff --git a/test/runtime/samples/store-destructuring/main.svelte b/test/runtime/samples/store-destructuring/main.svelte
