--- /dev/null
+++ b/test/runtime/samples/store-destructuring/main.svelte
@@ -0,0 +1,14 @@
+<script>
+	import { writable } from '../../../../store';
+
+	const foo = writable(0);
+	const bar = writable(0);
+
+	function update() {
+		({ foo: $foo, bar: $bar } = { foo: 1, bar: 2 });
+	}
+</script>
+
+<button on:click={update}>update</button>
+<p>foo: {$foo}</p>
+<p>bar: {$bar}</p>

